const { CloudWatchClient, GetMetricDataCommand } = require("@aws-sdk/client-cloudwatch");

const series = [
  { biz: "biz-ridge", cus: "cus_sample_alpha", dim: "ridge-alerts" },
  { biz: "biz-ridge", cus: "cus_sample_alpha", dim: "ridge-api-calls" },
  { biz: "biz-ridge", cus: "cus_sample_alpha", dim: "ridge-reports" },
  { biz: "biz-ridge", cus: "cus_sample_alpha", dim: "ridge-seats" },
  { biz: "biz-ridge", cus: "cus_sample_alpha", dim: "ridge-storage" },
  { biz: "biz-ridge", cus: "cus_sample_bravo", dim: "ridge-jobs" },
  { biz: "biz-ridge", cus: "cus_sample_bravo", dim: "ridge-minutes" },
  { biz: "biz-ridge", cus: "cus_sample_bravo", dim: "ridge-tasks" },
  { biz: "biz-ridge", cus: "cus_sample_bravo", dim: "ridge-scans" },
  { biz: "biz-vale", cus: "cus_sample_charlie", dim: "vale-hours" },
  { biz: "biz-vale", cus: "cus_sample_charlie", dim: "vale-messages" },
  { biz: "biz-vale", cus: "cus_sample_charlie", dim: "vale-units" },
];

(async () => {
  const cw = new CloudWatchClient({});
  for (const s of series) {
    const response = await cw.send(new GetMetricDataCommand({
      StartTime: new Date("2026-07-01T00:00:00Z"),
      EndTime: new Date("2026-08-01T00:00:00Z"),
      ScanBy: "TimestampAscending",
      MetricDataQueries: [{
        Id: "series",
        ReturnData: true,
        MetricStat: {
          Metric: {
            Namespace: "MeteringCo/Usage",
            MetricName: "AggregatedUsage",
            Dimensions: [
              { Name: "BusinessId", Value: s.biz },
              { Name: "CustomerId", Value: s.cus },
              { Name: "DimensionId", Value: s.dim },
            ],
          },
          Period: 3600,
          Stat: "Sum",
        },
      }],
    }));
    const result = (response.MetricDataResults || [])[0] || {};
    const values = result.Values || [];
    const timestamps = result.Timestamps || [];
    const total = values.reduce((a,b) => a+b, 0);
    console.log(JSON.stringify({
      ...s,
      count: values.length,
      total,
      samples: values.map((v,i) => ({ t: new Date(timestamps[i]).toISOString(), v })),
    }, null, 2));
  }
})().catch(e => { console.error(e); process.exit(1); });
'

